package top.monitorglobal.tv;
import android.content.*;import org.json.*;import java.util.*;
final class Prefs {
 static android.content.SharedPreferences get(Context c){return c.getSharedPreferences("monitor-tv",Context.MODE_PRIVATE);}
 static AlertTracker tracker(Context c){AlertTracker t=new AlertTracker();t.earthquakeReady=get(c).getBoolean("quakeReady",false);t.tsunamiReady=get(c).getBoolean("tsunamiReady",false);try{JSONArray catalogs=new JSONArray(get(c).getString("readyCatalogs","[]"));for(int i=0;i<Math.min(catalogs.length(),7);i++)t.readyCatalogs.add(catalogs.getString(i));JSONArray a=new JSONArray(get(c).getString("seen","[]"));for(int i=0;i<a.length()&&i<256;i++){JSONObject o=a.getJSONObject(i);AlertTracker.Seen seen=new AlertTracker.Seen(o.getString("v"),o.getLong("at"),o.optBoolean("tracked"));if(o.optJSONObject("bulletin")!=null)seen.bulletin=AlertCodec.read(o.getJSONObject("bulletin"));seen.provider=o.optString("provider","");if(seen.provider.isEmpty()&&o.getString("id").contains(":")){seen.provider=o.getString("id").split(":",2)[0];try{String network=new JSONArray(o.getString("v")).optString(5,"");if(List.of("USP","EMSC","GEOFON").contains(network))seen.provider=network;}catch(JSONException ignored){}}seen.magnitude=o.optDouble("mag",Double.NaN);seen.noticeMagnitude=o.optDouble("noticeMag",seen.magnitude);if(!Double.isFinite(seen.magnitude)&&o.getString("v").startsWith("[")){try{seen.magnitude=new JSONArray(o.getString("v")).optDouble(0,Double.NaN);}catch(JSONException ignored){}}t.seen.put(o.getString("id"),seen);}}catch(JSONException e){t.seen.clear();t.readyCatalogs.clear();t.earthquakeReady=false;t.tsunamiReady=false;}return t;}
 static void save(Context c,AlertTracker t){JSONArray a=new JSONArray();try{for(Map.Entry<String,AlertTracker.Seen> e:t.seen.entrySet()){JSONObject o=new JSONObject();o.put("id",e.getKey());o.put("v",e.getValue().version);o.put("at",e.getValue().at);o.put("tracked",e.getValue().tracked);o.put("provider",e.getValue().provider);if(e.getValue().bulletin!=null)o.put("bulletin",AlertCodec.write(e.getValue().bulletin));if(Double.isFinite(e.getValue().noticeMagnitude))o.put("noticeMag",e.getValue().noticeMagnitude);if(Double.isFinite(e.getValue().magnitude))o.put("mag",e.getValue().magnitude);a.put(o);}}catch(JSONException ignored){}get(c).edit().putString("seen",a.toString()).putString("readyCatalogs",new JSONArray(t.readyCatalogs).toString()).putBoolean("quakeReady",t.earthquakeReady).putBoolean("tsunamiReady",t.tsunamiReady).commit();}
 static void rememberReal(Context c,Alert a){try{String record=AlertCodec.write(a).toString();if(record.length()<=24000)get(c).edit().putString("lastReal",record).apply();}catch(JSONException ignored){}}
 static Alert lastReal(Context c){String record=get(c).getString("lastReal","");if(record.isEmpty()||record.length()>24000)return null;try{return AlertCodec.read(new JSONObject(record));}catch(JSONException e){return null;}}
 static void rememberRecovered(Context c,Alert a){try{String record=AlertCodec.write(a).toString();if(record.length()<=24000)get(c).edit().putString("lastRecovered",record).apply();}catch(JSONException ignored){}}
 static Alert lastReplay(Context c){Alert recovered=null;String record=get(c).getString("lastRecovered","");try{if(!record.isEmpty()&&record.length()<=24000)recovered=AlertCodec.read(new JSONObject(record));}catch(JSONException ignored){}return ReplaySelection.latest(lastReal(c),recovered);}
 static void rememberSummary(Context c,FeedClient.Snapshot snapshot){try{String record=SummaryRecord.encode(snapshot.alerts,snapshot.day,snapshot.asOf,snapshot.complete);android.content.SharedPreferences.Editor editor=get(c).edit().putString("lastSummary",record);if(snapshot.complete)editor.putString("lastCompletedSummary",record);editor.apply();}catch(JSONException ignored){}}
 static FeedClient.Snapshot lastSummary(Context c){try{return SummaryRecord.decode(get(c).getString("lastSummary",""));}catch(JSONException e){return null;}}
 static FeedClient.Snapshot lastCompletedSummary(Context c){try{FeedClient.Snapshot saved=SummaryRecord.decode(get(c).getString("lastCompletedSummary",""));if(saved.complete)return saved;}catch(JSONException ignored){}FeedClient.Snapshot old=lastSummary(c);return old!=null&&old.complete?old:null;}
 static void status(Context c,String s){get(c).edit().putString("status",s).apply();}
}
